"""Canonical capability definitions used by routing, handlers and tool discovery."""
from __future__ import annotations
from dataclasses import dataclass, asdict
from importlib import import_module
from typing import Any
from .capabilities.history import INPUT_SCHEMA as LAP_COMPARE_INPUT, OUTPUT_SCHEMA as LAP_COMPARE_OUTPUT
from .capabilities.segments import INPUT_SCHEMA as SEGMENT_COMPARE_INPUT, OUTPUT_SCHEMA as SEGMENT_COMPARE_OUTPUT


@dataclass(frozen=True)
class CapabilitySpec:
    name: str
    lane: str
    permission: str
    freshness_ms: int
    deadline_ms: int
    speech_priority: int
    handler_name: str | None
    version: str = "capability-v2"
    input_schema: dict[str, Any] | None = None
    output_schema: dict[str, Any] | None = None
    # Requested projection fields are not mandatory facts; handlers retain missing-data policy.
    requested_fields: tuple[str, ...] = ('player', 'rivals', 'raw')
    route_handler: str = 'strategy_snapshot_handler'
    default_query_text: str = '当前状态怎么样'
    fast_aliases: tuple[str, ...] = ()
    fast_alias_order: int = 1000


    def invoke(self, **kwargs: Any) -> tuple[str, str] | dict[str, Any]:
        if self.handler_name is None:
            raise ValueError("control_requires_output_coordinator")
        domain, name = self.handler_name.split(":", 1)
        handler = getattr(import_module(f".capabilities.{domain}", __package__), name)
        return handler(query_kind=self.name, **kwargs)

    def tool_schema(self) -> dict[str, Any]:
        if self.lane == 'analysis_tool':
            from copy import deepcopy
            return {'name':self.name,'input_schema':deepcopy(self.input_schema),'output_schema':deepcopy(self.output_schema),'policy':asdict(self)}
        return {"name":self.name, "input_schema":{"type":"object", "properties":{}, "additionalProperties":False},
                "output_schema":{"type":"object", "required":["speak_text","action_code"],
                                 "properties":{"speak_text":{"type":"string"},"action_code":{"type":"string"}}},
                "policy":asdict(self)}


