CONTROL_QUERY_KINDS = frozenset(name for name, spec in CAPABILITIES.items() if spec.lane == "control")
STRUCTURED_QUERY_KINDS = frozenset(name for name, spec in CAPABILITIES.items() if spec.lane == "structured")
EXPLAINER_QUERY_KINDS = frozenset(name for name, spec in CAPABILITIES.items() if spec.lane == "explainer")


def fast_intent_aliases() -> dict[str, tuple[str, ...]]:
    """Preserve explicit tie order and include newly registered capabilities."""
    specs = sorted(CAPABILITIES.values(), key=lambda spec: spec.fast_alias_order)
    return {spec.name: spec.fast_aliases for spec in specs if spec.fast_aliases and spec.lane != 'analysis_tool'}


def capability_speech_priority(query_kind: str | None) -> int:
    spec = CAPABILITIES.get(query_kind)
    return spec.speech_priority if spec is not None else 95
